// PreToolUse hook (Bash): worker-configuration.d.ts is generated by `wrangler types` and can
// drift even without a wrangler.jsonc change (the workerd runtime types it embeds move on their
// own between installs). Runs on every Bash call but only acts right before a `git commit`, so
// it's a no-op the rest of the time. Regenerates the types and stages the file so the commit
// that's about to run always includes an up-to-date worker-configuration.d.ts.
import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";

const input = JSON.parse(readFileSync(0, "utf-8"));
const command = input.tool_input?.command ?? "";

if (!/\bgit\s+commit\b/.test(command)) {
  process.exit(0);
}

const cwd = process.env.CLAUDE_PROJECT_DIR ?? process.cwd();

try {
  execSync("pnpm run cf-typegen", { cwd, stdio: "pipe" });
  execSync("git add worker-configuration.d.ts", { cwd, stdio: "pipe" });
} catch (error) {
  console.error(`sync-worker-types: failed to regenerate worker-configuration.d.ts: ${error.message}`);
}

process.exit(0);
